import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void __launch_bounds__(128, 8) conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int K,
    int stride, int padding, int dilation, int groups,
    int Dout, int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CoPerBlock = 4;

  const int tid = threadIdx.x;
  const int n       = blockIdx.z;
  const int co_tile = blockIdx.y;
  const int co_base = co_tile * CoPerBlock;

  const int Cin_per_group  = Cin  / groups;
  const int Cout_per_group = Cout / groups;

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides (contiguous NCDHW)
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(Cout, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  const int wsize_per_co = Cin_per_group * K * K * K;
  const int64_t sWco = (int64_t)wsize_per_co;

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cout, wsize_per_co),
      make_stride(sWco, Int<1>{})
  );

  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<CoPerBlock>{}, wsize_per_co),
      make_stride(wsize_per_co, Int<1>{})
  );

  // Cooperative load of weights for CoPerBlock output channels
  const int total_w = CoPerBlock * wsize_per_co;
  for (int idx = tid; idx < total_w; idx += Threads) {
    int cc  = idx / wsize_per_co;
    int rem = idx % wsize_per_co;
    int co  = co_base + cc;
    T val = T(0);
    if (co < Cout) {
      val = mW(co, rem);
    }
    sW(cc, rem) = val;
  }
  __syncthreads();

  // Precompute output coordinates for the PVec positions handled by this thread
  int p_idx[PVec];
  int od[PVec], oh[PVec], ow[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int rem = p;
      ow[i] = rem % Wout; rem /= Wout;
      oh[i] = rem % Hout; rem /= Hout;
      od[i] = rem;
    } else {
      ow[i] = 0; oh[i] = 0; od[i] = 0;
    }
  }

  int group0 = co_base / Cout_per_group;
  int co_last = co_base + CoPerBlock - 1;
  if (co_last >= Cout) co_last = Cout - 1;
  int group_last = co_last / Cout_per_group;
  bool same_group = (group0 == group_last);
  float acc[CoPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    float bval = 0.0f;
    if (co < Cout && B != nullptr) bval = (float)B[co];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[cc][i] = bval;
  }
  if (same_group) {
    int in_offset = group0 * Cin_per_group;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      int od_ = od[i], oh_ = oh[i], ow_ = ow[i];
      for (int kd = 0; kd < K; ++kd) {
        int id = od_ * stride - padding + kd * dilation;
        if ((unsigned)id >= (unsigned)D) continue;
        for (int kh = 0; kh < K; ++kh) {
          int ih = oh_ * stride - padding + kh * dilation;
          if ((unsigned)ih >= (unsigned)H) continue;
          for (int kw = 0; kw < K; ++kw) {
            int iw = ow_ * stride - padding + kw * dilation;
            if ((unsigned)iw >= (unsigned)Win) continue;
            int wbase = (kd * K + kh) * K + kw;
            for (int ci = 0; ci < Cin_per_group; ++ci) {
              int wrem = ci * K * K * K + wbase;
              float xval = (float)mX(in_offset + ci, id, ih, iw);
              #pragma unroll
              for (int cc = 0; cc < CoPerBlock; ++cc) {
                int co = co_base + cc;
                if (co >= Cout) continue;
                float wval = (float)sW(cc, wrem);
                acc[cc][i] += xval * wval;
              }
            }
          }
        }
      }
    }
  } else {
    #pragma unroll
    for (int cc = 0; cc < CoPerBlock; ++cc) {
      int co = co_base + cc;
      if (co >= Cout) continue;
      int g = co / Cout_per_group;
      int in_offset = g * Cin_per_group;
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        int p = p_idx[i];
        if (p >= P_total) continue;
        int od_ = od[i], oh_ = oh[i], ow_ = ow[i];
        for (int kd = 0; kd < K; ++kd) {
          int id = od_ * stride - padding + kd * dilation;
          if ((unsigned)id >= (unsigned)D) continue;
          for (int kh = 0; kh < K; ++kh) {
            int ih = oh_ * stride - padding + kh * dilation;
            if ((unsigned)ih >= (unsigned)H) continue;
            for (int kw = 0; kw < K; ++kw) {
              int iw = ow_ * stride - padding + kw * dilation;
              if ((unsigned)iw >= (unsigned)Win) continue;
              int wbase = (kd * K + kh) * K + kw;
              for (int ci = 0; ci < Cin_per_group; ++ci) {
                int wrem = ci * K * K * K + wbase;
                float xval = (float)mX(in_offset + ci, id, ih, iw);
                float wval = (float)sW(cc, wrem);
                acc[cc][i] += xval * wval;
              }
            }
          }
        }
      }
    }
  }
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    if (co >= Cout) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(co, od[i], oh[i], ow[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv3d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, K, K, K]");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Win = x.size(4);

  int64_t Cout = w.size(0);
  int64_t K    = w.size(2);
  TORCH_CHECK(w.size(3) == K && w.size(4) == K, "kernel must be cubic");
  TORCH_CHECK(w.size(1) == Cin / groups, "weight in-channels must equal Cin/groups");

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  TORCH_CHECK(groups > 0 && Cin % groups == 0 && Cout % groups == 0, "invalid groups");

  int64_t Dout = (D   + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Hout = (H   + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CoPerBlock = 4;

  const int64_t P_total = Dout * Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((Cout + CoPerBlock - 1) / CoPerBlock),
      (unsigned)N
  );

  int64_t Cin_per_group = Cin / groups;
  size_t smem_bytes = (size_t)CoPerBlock * Cin_per_group * K * K * K * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Win,
      (int)Cout, (int)K,
      (int)stride, (int)padding, (int)dilation, (int)groups,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution with a square kernel, implemented with a custom
    cooperative-tiled CUDA kernel that uses CuTe tensors/layouts for indexing.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        K = self.kernel_size
        Cin_per_group = self.in_channels // self.groups

        self.weight = nn.Parameter(torch.empty(self.out_channels, Cin_per_group, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.weight.size(1) * self.weight.size(2) * self.weight.size(3) * self.weight.size(4)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

